import { init, EChartsType } from '@/src/echarts.all';

describe('aria_ssr', function () {

    let chart: EChartsType;

    afterEach(function () {
        chart && chart.dispose();
        chart = null;
    });

    it('should not throw when aria is enabled in SSR mode', function () {
        expect(function () {
            chart = init(null, null, {
                renderer: 'svg',
                ssr: true,
                width: 400,
                height: 300
            });
            chart.setOption({
                aria: {
                    enabled: true,
                    decal: {
                        show: true
                    }
                },
                xAxis: {
                    type: 'category',
                    data: ['A', 'B', 'C']
                },
                yAxis: {},
                series: [{
                    type: 'bar',
                    data: [1, 2, 3]
                }]
            });
        }).not.toThrow();

        // Rendering still works in SSR mode.
        expect(typeof chart.renderToSVGString()).toEqual('string');
    });

    it('should still apply aria decal in SSR mode', function () {
        chart = init(null, null, {
            renderer: 'svg',
            ssr: true,
            width: 400,
            height: 300
        });
        chart.setOption({
            aria: {
                enabled: true,
                decal: {
                    show: true
                }
            },
            series: [{
                type: 'pie',
                data: [{ value: 1, name: 'a' }, { value: 2, name: 'b' }]
            }]
        });

        const data = (chart as any).getModel().getSeries()[0].getData();
        expect(data.getItemVisual(0, 'decal')).toBeTruthy();
    });
});

