import { EChartsType } from '@/src/echarts.all';
import { createChart } from '../../core/utHelper';
import SeriesModel from '@/src/model/Series';

describe('aria', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart && chart.dispose();
        chart = null;
    });

    function getSeriesData(chart: EChartsType) {
        const seriesModel = (chart as any).getModel().getSeries()[0] as SeriesModel;
        return seriesModel.getData();
    }

    const source = [
        ['product', 'count', 'helperA', 'helperB'],
        ['Matcha', 51, 1234.5, 6789.5],
        ['Milk', 82, 2345.5, 7891.5]
    ];

    it('should exclude the dimensions in aria.label.data.excludeDimensionId', function () {
        chart.setOption({
            aria: {
                enabled: true,
                label: {
                    data: {
                        excludeDimensionId: [2, 3]
                    }
                }
            },
            dataset: {
                source: source
            },
            xAxis: { type: 'category' },
            yAxis: {},
            series: [{ type: 'bar' }]
        });

        const ariaLabel = chart.getZr().dom.getAttribute('aria-label');

        // (a) The excluded columns are not spoken.
        expect(ariaLabel).not.toContain('1234.5');
        expect(ariaLabel).not.toContain('6789.5');
        expect(ariaLabel).not.toContain('2345.5');
        expect(ariaLabel).not.toContain('7891.5');

        // (b) The remaining columns are still there, in their original order.
        expect(ariaLabel).toContain('Matcha');
        expect(ariaLabel).toContain('Milk');
        expect(ariaLabel).toContain('0, 51');
        expect(ariaLabel).toContain('1, 82');

        // (c) The series data is left untouched.
        const data = getSeriesData(chart);
        expect(data.getValues(0)).toEqual([0, 51, 1234.5, 6789.5]);
        expect(data.getValues(1)).toEqual([1, 82, 2345.5, 7891.5]);
    });

    it('should keep all values when excludeDimensionId is not specified', function () {
        chart.setOption({
            aria: {
                enabled: true
            },
            dataset: {
                source: source
            },
            xAxis: { type: 'category' },
            yAxis: {},
            series: [{ type: 'bar' }]
        });

        const ariaLabel = chart.getZr().dom.getAttribute('aria-label');
        expect(ariaLabel).toContain('0, 51, 1234.5, 6789.5');
        expect(ariaLabel).toContain('1, 82, 2345.5, 7891.5');

        const data = getSeriesData(chart);
        expect(data.getValues(0)).toEqual([0, 51, 1234.5, 6789.5]);
    });

    it('should exclude leading dimensions and keep the rest in order', function () {
        chart.setOption({
            aria: {
                enabled: true,
                label: {
                    data: {
                        excludeDimensionId: [0, 2]
                    }
                }
            },
            dataset: {
                source: source
            },
            xAxis: { type: 'category' },
            yAxis: {},
            series: [{ type: 'bar' }]
        });

        const ariaLabel = chart.getZr().dom.getAttribute('aria-label');
        expect(ariaLabel).toContain('51, 6789.5');
        expect(ariaLabel).toContain('82, 7891.5');
        expect(ariaLabel).not.toContain('1234.5');
        expect(ariaLabel).not.toContain('2345.5');

        const data = getSeriesData(chart);
        expect(data.getValues(0)).toEqual([0, 51, 1234.5, 6789.5]);
        expect(data.getValues(1)).toEqual([1, 82, 2345.5, 7891.5]);
    });
});

